tml_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Single fused kernel for TripletMarginLoss (p=2, reduction='mean'):
//   loss_i = max(||a_i - p_i||_2 - ||a_i - n_i||_2 + margin, 0)
//   output = mean_i(loss_i)
// Each CTA handles one triplet (one row of length D), performs a cooperative
// block reduction of the two squared-distance accumulations, then atomically
// accumulates loss_i / B into the scalar output.
template <int Threads>
__global__ void triplet_margin_loss_kernel(
    const float* __restrict__ A,
    const float* __restrict__ P,
    const float* __restrict__ Nn,
    float* __restrict__ Out,
    int64_t B,
    int64_t D,
    float margin,
    float invB)
{
  const int64_t b   = blockIdx.x;
  const int     tid = threadIdx.x;

  // Full tensors as CuTe global tensors: (B, D) row-major
  auto mA = make_tensor(make_gmem_ptr(A),  make_shape(B, D), make_stride(D, Int<1>{}));
  auto mP = make_tensor(make_gmem_ptr(P),  make_shape(B, D), make_stride(D, Int<1>{}));
  auto mN = make_tensor(make_gmem_ptr(Nn), make_shape(B, D), make_stride(D, Int<1>{}));

  // Vectorized (float4) views of this block's row
  const int64_t D4 = D / 4;
  auto gA4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(A  + b * D)), make_shape(D4));
  auto gP4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(P  + b * D)), make_shape(D4));
  auto gN4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(Nn + b * D)), make_shape(D4));

  float acc_pos = 0.0f;
  float acc_neg = 0.0f;

  // Main vectorized sweep over the feature dimension
  for (int64_t i = tid; i < D4; i += Threads) {
    float4 a = gA4(i);
    float4 p = gP4(i);
    float4 n = gN4(i);

    float dp0 = a.x - p.x;
    float dp1 = a.y - p.y;
    float dp2 = a.z - p.z;
    float dp3 = a.w - p.w;
    acc_pos += dp0 * dp0 + dp1 * dp1 + dp2 * dp2 + dp3 * dp3;

    float dn0 = a.x - n.x;
    float dn1 = a.y - n.y;
    float dn2 = a.z - n.z;
    float dn3 = a.w - n.w;
    acc_neg += dn0 * dn0 + dn1 * dn1 + dn2 * dn2 + dn3 * dn3;
  }

  // Scalar tail (handles D % 4 != 0)
  for (int64_t i = D4 * 4 + tid; i < D; i += Threads) {
    float dp = mA(b, i) - mP(b, i);
    float dn = mA(b, i) - mN(b, i);
    acc_pos += dp * dp;
    acc_neg += dn * dn;
  }

  // Cooperative block reduction of both partial sums
  __shared__ float sPos[Threads];
  __shared__ float sNeg[Threads];

  sPos[tid] = acc_pos;
  sNeg[tid] = acc_neg;
  __syncthreads();

  #pragma unroll
  for (int s = Threads / 2; s > 32; s >>= 1) {
    if (tid < s) {
      sPos[tid] += sPos[tid + s];
      sNeg[tid] += sNeg[tid + s];
    }
    __syncthreads();
  }

  // Final warp-level reduction via shuffles
  if (tid < 32) {
    float vp = sPos[tid] + sPos[tid + 32];
    float vn = sNeg[tid] + sNeg[tid + 32];
    #pragma unroll
    for (int s = 16; s > 0; s >>= 1) {
      vp += __shfl_down_sync(0xffffffffu, vp, s);
      vn += __shfl_down_sync(0xffffffffu, vn, s);
    }
    if (tid == 0) {
      float d_pos = sqrtf(vp);
      float d_neg = sqrtf(vn);
      float loss  = fmaxf(d_pos - d_neg + margin, 0.0f);
      // Fused mean reduction: each block contributes loss_i / B
      atomicAdd(Out, loss * invB);
    }
  }
}

torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                          torch::Tensor positive,
                                          torch::Tensor negative,
                                          double margin)
{
  TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
              "All inputs must be CUDA tensors");
  TORCH_CHECK(anchor.scalar_type() == at::kFloat &&
              positive.scalar_type() == at::kFloat &&
              negative.scalar_type() == at::kFloat,
              "All inputs must be float32");
  TORCH_CHECK(anchor.sizes() == positive.sizes() &&
              anchor.sizes() == negative.sizes(),
              "anchor, positive and negative must have the same shape");
  TORCH_CHECK(anchor.dim() >= 2, "Inputs must have at least 2 dimensions [B, ...]");

  auto a_c = anchor.contiguous();
  auto p_c = positive.contiguous();
  auto n_c = negative.contiguous();

  const int64_t B = (int64_t)a_c.size(0);
  const int64_t D = (int64_t)(a_c.numel() / a_c.size(0));

  auto out = torch::zeros({}, a_c.options());

  constexpr int Threads = 256;
  dim3 block(Threads);
  dim3 grid((unsigned)B);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  const float invB = 1.0f / (float)B;

  triplet_margin_loss_kernel<Threads><<<grid, block, 0, stream>>>(
      a_c.data_ptr<float>(),
      p_c.data_ptr<float>(),
      n_c.data_ptr<float>(),
      out.data_ptr<float>(),
      B, D,
      (float)margin,
      invB
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "triplet_margin_loss_kernel launch failed: ",
              cudaGetErrorString(err));

  return out;
}
"""

