class ModelNew(nn.Module):
    """
    Triplet Margin Loss (p=2, reduction='mean') implemented with a single
    fused CuTe/CUDA kernel: per-triplet distances, hinge, and mean reduction
    are all computed in one kernel launch.

    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self._ext = tml_ext

    def forward(self, anchor, positive, negative):
        return self._ext.triplet_margin_loss_forward(
            anchor, positive, negative, self.margin
        )
